module.exports = "<ng-template #chatContent>\n  <section class=\"bmb_chat-card\">\n    <bmb-home-card\n      [leftIcon]=\"mode() === 'chat' ? undefined : leftIcon()\"\n      [componentTitle]=\"componentTitle() || title() || ('home_card_chat.title' | translate)\"\n      [subtitle]=\"subtitle() || ('home_card_chat.subtitle' | translate)\"\n      [isMobile]=\"isMobile()\"\n      [actionHeaders]=\"chatActionHeaders()\"\n      [bgIconAppearance]=\"bgIconAppearance()\"\n      [contentPadding]=\"'xs'\"\n      [isExpanded]=\"isChatCardOpen()\"\n      [(currentBot)]=\"currentBot\"\n      (onExpandClick)=\"handleChat()\"\n      (onClose)=\"handleClose()\"\n      (onBack)=\"handleBack()\"\n    >\n      <div class=\"bmb_chat-card-container\">\n        @for (message of messagesHistory(); track $index) {\n          <bmb-chat-bubble [message]=\"message\" />\n        }\n      </div>\n      <div class=\"bmb_chat-card-chatBar\">\n        <bmb-chat-bar\n          [placeholder]=\"placeholder()\"\n          [botList]=\"botList()\"\n          [(currentBot)]=\"currentBot\"\n          [(isLoading)]=\"isLoading\"\n          (onSendMessage)=\"handleSend($event)\"\n        />\n      </div>\n    </bmb-home-card>\n  </section>\n</ng-template>\n\n@if (mode() === 'expanded') {\n  <ng-container *ngTemplateOutlet=\"chatContent\" />\n}\n\n<ng-template #contentTemplate>\n  <div class=\"bmb_chat-card-chat-content\">\n    <ng-container *ngTemplateOutlet=\"chatContent\" />\n  </div>\n</ng-template>\n\n@if (mode() === 'compact') {\n  <bmb-action-icon\n    class=\"bmb_chat-card-bot\"\n    [icon]=\"currentBot()?.icon!\"\n    [alt]=\"currentBot()?.name!\"\n    [iconSize]=\"40\"\n    [isSVGTemplate]=\"true\"\n    (buttonClick)=\"openChatFromCompact()\"\n  >\n    <ng-template #customActionIcon>\n      <bmb-bot-icon [iconName]=\"currentBot()?.icon!\" />\n    </ng-template>\n  </bmb-action-icon>\n}\n\n<ng-template #chatBarActionsTemplate>\n  <bmb-action-menu\n    class=\"bmb_chat-card-chat-actions\"\n    [showHeader]=\"false\"\n    componentTitle=\"Selecciona una opción\"\n  >\n    <ng-template>\n      <bmb-item\n        label=\"Expandir Chat\"\n        [isButton]=\"true\"\n        (action)=\"handleExpand()\"\n      />\n    </ng-template>\n    <ng-template>\n      <bmb-item\n        label=\"Iniciar nuevo chat\"\n        [isButton]=\"true\"\n        (action)=\"handleExpand()\"\n      />\n    </ng-template>\n  </bmb-action-menu>\n</ng-template>\n";

